import React from "react";
import { useParams } from "react-router-dom";

import "./../../css/service-detail.css";

import SpecialistsSection from "./SpecialistsSectionComponent";


class ServiceDetailContent extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      service: null,
      loading: true,
      error: false,

      liked: false,
      activeTab: "before",
    };
  }

  componentDidMount() {
    const { id } = this.props;

    fetch(`http://127.0.0.1:8000/api/services/${id}`)
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت اطلاعات خدمت");
        }

        return response.json();
      })
      .then((result) => {
        if (result.success) {
          this.setState({
            service: result.data,
            loading: false,
            error: false,
          });
        } else {
          this.setState({
            loading: false,
            error: true,
          });
        }
      })
      .catch((error) => {
        console.error(error);

        this.setState({
          loading: false,
          error: true,
        });
      });
  }

  handleBack = () => {
    if (this.props.navigate) {
      this.props.navigate("/services");
    } else {
      window.history.back();
    }
  };

  handleLike = () => {
    this.setState((prevState) => ({
      liked: !prevState.liked,
    }));
  };

  handleTabChange = (tab) => {
    this.setState({
      activeTab: tab,
    });
  };

  handleShare = () => {
    const { service } = this.state;

    if (navigator.share) {
      navigator.share({
        title: service?.name || "خدمت",
        text: service?.short_description || "",
        url: window.location.href,
      });
    }
  };

  renderStars = () => {
    return (
      <span className="detail-stars">
        {[1, 2, 3, 4, 5].map((star) => (
          <svg
            key={star}
            width="14"
            height="14"
            viewBox="0 0 24 24"
            fill="currentColor"
          >
            <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
          </svg>
        ))}
      </span>
    );
  };

  render() {
    const {
      service,
      loading,
      error,
      liked,
      activeTab,
    } = this.state;

    if (loading) {
      return (
        <div className="scroll-area">
          <div className="detail-body">
            در حال دریافت اطلاعات خدمت...
          </div>
        </div>
      );
    }

    if (error || !service) {
      return (
        <div className="scroll-area">
          <div className="detail-body">
            دریافت اطلاعات خدمت با خطا مواجه شد.
          </div>
        </div>
      );
    }

    const rating = service.rating
      ? Number(service.rating).toFixed(1)
      : "0.0";

    const reviews = service.reviews || 0;

    return (
      <>
        {/* ================= HEADER ================= */}

        <header className="page-header">

          <button
            className="icon-btn"
            aria-label="بازگشت"
            onClick={this.handleBack}
          >
            <svg
              width="18"
              height="18"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="m15 18-6-6 6-6" />
            </svg>
          </button>

          <h1 className="page-title">
            {service.name}
          </h1>

          <div className="head-actions">

            {/* Like */}
            <button
              className={`icon-btn ${liked ? "liked" : ""}`}
              aria-label="علاقه‌مندی"
              onClick={this.handleLike}
            >
              <svg
                width="17"
                height="17"
                viewBox="0 0 24 24"
                fill={liked ? "currentColor" : "none"}
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.6l-1-1a5.5 5.5 0 0 0-7.8 7.8l1 1L12 21l7.8-7.8 1-1a5.5 5.5 0 0 0 0-7.6z" />
              </svg>
            </button>

            {/* Share */}
            <button
              className="icon-btn"
              aria-label="اشتراک‌گذاری"
              onClick={this.handleShare}
            >
              <svg
                width="17"
                height="17"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <circle cx="18" cy="5" r="3" />
                <circle cx="6" cy="12" r="3" />
                <circle cx="18" cy="19" r="3" />
                <path d="m8.6 13.5 6.8 3.9M15.4 6.6 8.6 10.5" />
              </svg>
            </button>

          </div>
        </header>


        <div className="scroll-area">

          {/* ================= HERO ================= */}

          <div className="detail-hero">

            <div className="detail-hero-bg"></div>

            <div className="detail-hero-swirl">

              <svg
                width="120"
                height="120"
                viewBox="0 0 120 120"
                fill="none"
                opacity=".85"
              >
                <path
                  d="M60 15c24 0 45 21 45 45s-21 45-45 45S15 84 15 60"
                  stroke="#fff"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeDasharray="4 8"
                />

                <path
                  d="M60 30c17 0 30 13 30 30S77 90 60 90"
                  stroke="#fff"
                  strokeWidth="2"
                  strokeLinecap="round"
                />

                <circle
                  cx="60"
                  cy="60"
                  r="9"
                  fill="#fff"
                  fillOpacity=".9"
                />
              </svg>

            </div>

            {/* Rating */}

            <div className="hero-badge-rate">

              <svg
                width="13"
                height="13"
                viewBox="0 0 24 24"
                fill="currentColor"
              >
                <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z" />
              </svg>

              {rating}

              {" · "}

              {reviews} نظر

            </div>

            {/* Price */}

            <div className="hero-badge-price">
              {Number(service.price || 0).toLocaleString("fa-IR")} تومان
            </div>

          </div>


          {/* ================= BODY ================= */}

          <div className="detail-body">

            {/* Title */}

            <h2 className="detail-title">
              {service.name}
            </h2>


            {/* Description */}

            {service.short_description && (
              <p className="detail-desc">
                {service.short_description}
              </p>
            )}


            {/* Rating */}

            <div className="detail-rate-row">

              {this.renderStars()}

              <span className="detail-rn">
                {rating}
              </span>

              <span>
                ({reviews} نظر)
              </span>

              <span className="detail-sep">
                ·
              </span>

              <span className="detail-dur-inline">

                <svg
                  width="13"
                  height="13"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle
                    cx="12"
                    cy="12"
                    r="10"
                  />

                  <path d="M12 6v6l4 2" />

                </svg>

                {service.duration_minutes} دقیقه

              </span>

            </div>


            {/* ================= CTA ================= */}

            <div className="cta-row">

              <button className="btn-outline">
                دریافت مشاوره
              </button>

              <button className="btn-solid">
                رزرو نوبت
              </button>

            </div>


            {/* ================= INFO ================= */}

            <div className="info-grid">

              {/* Duration */}

              <div className="info-box">

                <span className="info-ic">

                  <svg
                    width="17"
                    height="17"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <circle cx="12" cy="12" r="10" />
                    <path d="M12 6v6l4 2" />
                  </svg>

                </span>

                <div>

                  <div className="info-l">
                    مدت‌زمان
                  </div>

                  <div className="info-v">
                    {service.duration_minutes} دقیقه
                  </div>

                </div>

              </div>


              {/* تعداد جلسات فعلاً API ندارد */}

              {/* دوره نقاهت فعلاً API ندارد */}

              {/* مناسب برای فعلاً API ندارد */}

            </div>


            {/* ================= ARTICLE ================= */}

            {service.article_content && (
              <>
                <div className="detail-divider"></div>

                <h3 className="detail-h2">
                  این درمان چیست؟
                </h3>

                <p
                  className="detail-desc"
                  style={{ marginBottom: 0 }}
                >
                  {service.article_content}
                </p>

                <a
                  href="#!"
                  className="read-more"
                  onClick={(event) => event.preventDefault()}
                >
                  بیشتر بخوانید

                  <svg
                    width="13"
                    height="13"
                    viewBox="0 0 24 24"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="m6 9 6 6 6-6" />
                  </svg>

                </a>
              </>
            )}


            {/* ================= SUITABLE ================= */}

            {/* فعلاً API اطلاعات این قسمت را ندارد */}


            {/* ================= HOW IT WORKS ================= */}

            {/* فعلاً API اطلاعات این قسمت را ندارد */}


            {/* ================= EXPECTATIONS ================= */}

            {/* فعلاً API اطلاعات این قسمت را ندارد */}


            {/* ================= AFTER CARE ================= */}

            {/* فعلاً API اطلاعات این قسمت را ندارد */}


            {/* ================================================= */}
            {/* SPECIALISTS                                      */}
            {/* ================================================= */}

            {service.staff?.length > 0 && (
              <>
                <div className="detail-divider"></div>

                <h3 className="detail-h2">
                  متخصصین موجود
                </h3>

                <div className="spec-list">

                  {service.staff.map((staff) => (
                    <SpecialistsSection
                      key={staff.id}
                      specialist={staff}
                    />
                  ))}

                </div>
              </>
            )}


            {/* ================================================= */}
            {/* REVIEWS                                          */}
            {/* ================================================= */}

            {/* 
              فعلاً API اطلاعات تک‌تک نظرات را برنمی‌گرداند.
              فقط reviews و review_count داریم.
              
              وقتی API آرایه reviews را برگرداند،
              اینجا به همین شکل map می‌کنیم:

              {service.reviews?.map((review) => (
                <ClientReviews
                  key={review.id}
                  review={review}
                />
              ))}
            */}


            {/* ================================================= */}
            {/* FAQ                                              */}
            {/* ================================================= */}

            {/* فعلاً API اطلاعات FAQ ندارد */}


            {/* ================================================= */}
            {/* RELATED SERVICES                                  */}
            {/* ================================================= */}

            {/* فعلاً API اطلاعات خدمات مرتبط ندارد */}


            {/* ================= NOT SURE ================= */}

            <div className="notsure-card">

              <div className="notsure-ic">

                <svg
                  width="24"
                  height="24"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
                </svg>

              </div>

              <div className="notsure-t">
                هنوز مطمئن نیستید؟
              </div>

              <p className="notsure-s">
                قبل از تصمیم‌گیری با یک متخصص صحبت کنید.
                بدون هیچ تعهدی.
              </p>

              <div className="notsure-btns">

                <button className="btn-solid">
                  دریافت مشاوره
                </button>

                <button className="btn-outline">
                  رزرو نوبت
                </button>

              </div>

            </div>

          </div>

        </div>


        {/* ================= STICKY CTA ================= */}

        <div className="sticky-cta">

          <button className="btn-outline">
            دریافت مشاوره
          </button>

          <button className="btn-solid">
            رزرو نوبت
          </button>

        </div>
      </>
    );
  }
}


function ServiceDetail(props) {
  const { id } = useParams();

  return (
    <ServiceDetailContent
      {...props}
      id={id}
    />
  );
}


export default ServiceDetail;
